    Bug 2024842 - Fix comm/mail/test/browser/message-reader/browser_convertToEventOrTask.js | test_convertToEvent - Test timed out (due to More button outside of viewport). r=john.bieling

    The today pane is covering the More menu. Hide it.

    Differential Revision: https://phabricator.services.mozilla.com/D290749

diff --git a/mail/test/browser/message-reader/browser_convertToEventOrTask.js b/mail/test/browser/message-reader/browser_convertToEventOrTask.js
index 4936140561c..820a180dd01 100644
--- a/mail/test/browser/message-reader/browser_convertToEventOrTask.js
+++ b/mail/test/browser/message-reader/browser_convertToEventOrTask.js
@@ -37,10 +37,26 @@ add_setup(async function () {
   // Enable home calendar.
   cal.manager.getCalendars()[0].setProperty("disabled", false);

-  registerCleanupFunction(() => {
+  // Hide the today pane so the More button we'll use is sure to be inside
+  // the viewport.
+  EventUtils.synthesizeKey("VK_F11", {}, window);
+  await new Promise(resolve => setTimeout(resolve));
+  Assert.ok(
+    document.getElementById("today-pane-panel").hasAttribute("collapsed"),
+    "today pane should not be shown"
+  );
+
+  registerCleanupFunction(async () => {
     folder.deleteSelf(null);
     cal.manager.getCalendars()[0].setProperty("disabled", true);
     document.documentElement.focus();
+
+    EventUtils.synthesizeKey("VK_F11", {}, window);
+    await new Promise(resolve => setTimeout(resolve));
+    Assert.ok(
+      !document.getElementById("today-pane-panel").hasAttribute("collapsed"),
+      "today pane should beshown"
+    );
   });
 });
